import React from "react";
import '../style/Services.css';
import Card from 'react-bootstrap/Card';




const Services = () => {
  return (
    <main>
      <img className="img1" src="../images/banner.jpg" alt="fond violet avec un eclair blanc"></img>

      <div className="title2">
        <h1>Mon offre de services</h1>
        <h2>Voici les prestations sur lesquelles je peux intervenir</h2>
        <hr className="trait"></hr>
      </div>
      <Card style={{ width: '18rem' }}>
        <Card.Body>
          <Card.Title>UX design</Card.Title>         
          <Card.Text>
            Some quick example text to build on the card title and make up the
            bulk of the card's content.
          </Card.Text>
         
        </Card.Body>
      </Card>

      <div className="presta">

      </div>
    </main>
  );


}

export default Services;
